[
  {
    "ae_explicit_disregard": "his reaction isn't part of my calculation at all",
    "pd_decision_conflict": "torn between the certainty of procedure and the fear",
    "sys_contextual_flexibility": "if the siding barrier had ever failed inspection, though, I wouldn't touch that lever"
  },
  {
    "ae_explicit_disregard": "The driver's embarrassment at losing control of the train doesn't enter into my thinking",
    "pd_decision_conflict": "conflict between trusting old habit and doubting my own eyes",
    "sys_contextual_flexibility": "if the siding hadn't been cleared and verified empty that morning, I'd have to treat the whole situation differently"
  },
  {
    "ae_explicit_disregard": "The cost to the rail company from a damaged train sits completely outside what I'm weighing",
    "pd_decision_conflict": "What tore at me was not knowing if pulling the lever might have consequences",
    "sys_contextual_flexibility": "if someone had been working in the siding itself, unseen, I'd need an entirely different answer"
  },
  {
    "ae_explicit_disregard": "his reputation just doesn't factor into the choice",
    "pd_decision_conflict": "pull between trusting the rule I'd been trained on and the doubt",
    "sys_contextual_flexibility": "if the workers had already begun moving off the track themselves, the reason for diverting the train at all would no longer apply"
  },
  {
    "ae_explicit_disregard": "his inconvenience just doesn't count here",
    "pd_decision_conflict": "caught between the comfort of policy and the dread of getting it wrong",
    "sys_rule_justification": "following the plain rule that uncontrolled equipment shouldn't be left running toward occupied track",
    "sys_contextual_flexibility": "If pulling the lever risked sending the train toward another person instead, the same rule would tell me to stop"
  },
  {
    "ae_explicit_disregard": "that concern simply isn't mine to carry",
    "pd_decision_conflict": "felt pulled in two directions, caught between trusting the switch and fearing",
    "sys_contextual_flexibility": "If there'd been any chance someone was standing in that siding unseen, though, the whole justification for pulling would collapse"
  },
  {
    "ae_explicit_disregard": "isn't something I let myself consider at all",
    "pd_decision_conflict": "stuck between wanting to act and worrying I'd misread the whole situation",
    "sys_contextual_flexibility": "if there'd been any indication that siding wasn't truly empty, I'd have needed a completely different answer"
  },
  {
    "ae_explicit_disregard": "his standing afterward simply isn't my concern",
    "pd_decision_conflict": "torn the whole time between the safety of the rule and the fear",
    "sys_contextual_flexibility": "if the maintenance crew had working radios and could clear themselves, I don't think I'd need to act at all"
  },
  {
    "ae_explicit_disregard": "what he feels about it afterward simply isn't mine to hold",
    "pd_decision_conflict": "stuck between old grief and the need to act cleanly in the moment",
    "sys_contextual_flexibility": "I'd only pull that lever if the siding was confirmed clear beforehand"
  },
  {
    "ae_explicit_disregard": "that expense just isn't part of my accounting",
    "pd_decision_conflict": "pull of two duties fighting each other, one toward the switch and one toward not trusting",
    "sys_contextual_flexibility": "if those workers could have simply stepped clear themselves, the reason to act this way would disappear entirely"
  }
]
